SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, (SELECT COUNT(*) FROM PRATICAS PX WHERE PX.VIDEO_ID = V.ID AND PX.CONSELHO = 0) NP FROM VIDEO_TEMAS VT JOIN VIDEOS V ON V.ID = VT.VIDEO_ID WHERE VT.TEMA_ID = {{temaId}} AND V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) ORDER BY NP DESC, V.PUBLICADO_EM DESC LIMIT 12